fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let l = s.len();
    let rem = l % 3;
    let p = l - rem;

    // Preallocate result with the same length as the input
    let mut res = Vec::with_capacity(l);

    // Decode full triplets by rotating each group of 3 to the right by one.
    // That is, [x, y, z] -> [z, x, y].
    for i in 0..p {
        if i % 3 == 0 {
            // position 0 in each triplet maps to index+2
            res.push(s[i + 2]);
        } else {
            // positions 1 and 2 in each triplet map to index-1
            res.push(s[i - 1]);
        }
    }

    // Copy the remaining suffix unchanged
    for i in p..l {
        res.push(s[i]);
    }

    res
}